SELECT e.Id EmployeeId,e.IqamaNo,e.FullNameAr,r.Id RiderProfileId,e.Status FROM app.Employees e JOIN app.RiderProfiles r ON r.EmployeeId=e.Id WHERE e.IqamaNo='2535062091' AND e.IsDeleted=0 AND r.IsDeleted=0;
SELECT a.Id,a.ExternalAccountId,p.Code,a.Status,a.IsDeleted FROM app.PlatformRiderAccounts a JOIN platform.ClientPlatforms p ON p.Id=a.ClientPlatformId WHERE a.ExternalAccountId='472551';
SELECT x.*,a.ExternalAccountId,p.Code FROM app.RiderClientAssignments x JOIN app.PlatformRiderAccounts a ON a.Id=x.PlatformRiderAccountId JOIN platform.ClientPlatforms p ON p.Id=a.ClientPlatformId WHERE x.RiderProfileId IN(SELECT r.Id FROM app.RiderProfiles r JOIN app.Employees e ON e.Id=r.EmployeeId WHERE e.IqamaNo='2535062091') OR a.ExternalAccountId='472551';
SELECT s.* FROM jahez_v2.AccountSessions s WHERE s.RiderProfileId IN(SELECT r.Id FROM app.RiderProfiles r JOIN app.Employees e ON e.Id=r.EmployeeId WHERE e.IqamaNo='2535062091') OR s.PlatformRiderAccountId IN(SELECT Id FROM app.PlatformRiderAccounts WHERE ExternalAccountId='472551');
